namespace fs = std::filesystem;

namespace layer {

namespace {

constexpr const char* kConsoleFile = "pulselayer_console.cpp";
constexpr const char* kConsoleSource =
    "// Generated by Pulse Layer (Debug builds only).\n"
    "// Run from Pulse Layer, the program's stdout goes to a pipe, which the C runtime\n"
    "// buffers fully: std::cout / printf output would show up only every 4 KB or at exit.\n"
    "// Unbuffered, every line appears in Application Output as it is written.\n"
    "#include <cstdio>\n"
    "#include <cstdlib>\n"
    "namespace {\n"
    "struct PulseLayerConsole {\n"
    "  PulseLayerConsole() {\n"
    "    if (!std::getenv(\"PULSELAYER_CONSOLE\")) return;\n"
    "    std::setvbuf(stdout, nullptr, _IONBF, 0);\n"
    "    std::setvbuf(stderr, nullptr, _IONBF, 0);\n"
    "  }\n"
    "} pulselayer_console;\n"
    "} // namespace\n";

// what the CMake cache was made for: a change means configuring again
std::string kit_stamp(const Kit& k) { return k.id + (k.libcxx_dir.empty() ? "" : "|libc++:" + k.libcxx_dir); }

std::string read_file(const fs::path& p) {
  std::ifstream in(p, std::ios::binary);
  std::stringstream ss;
  ss << in.rdbuf();
  return ss.str();
}

// Writes only when the content changed, so unchanged files do not trigger rebuilds.
void write_if_changed(const fs::path& p, const std::string& content) {
  std::error_code ec;
  if (fs::exists(p, ec) && read_file(p) == content) return;
  fs::create_directories(p.parent_path(), ec);
  std::ofstream out(p, std::ios::binary);
  out << content;
}

std::string cmake_path(const std::string& p) {
  std::string s = p;
  for (auto& c : s)
    if (c == '\\') c = '/';
  return s;
}

pulseui::Diagnostic::Severity severity_of(const std::string& s) {
  if (s.find("warning") != std::string::npos) return pulseui::Diagnostic::Warning;
  if (s.find("note") != std::string::npos) return pulseui::Diagnostic::Note;
  return pulseui::Diagnostic::Error;
}

} // namespace

bool parse_issue(const std::string& line, Issue& out) {
  // MSVC: D:\x\main.cpp(12,5): error C2065: 'foo': undeclared identifier
  static const std::regex msvc(R"(^\s*(.+?)\((\d+)(?:,(\d+))?\)\s*:\s*(fatal error|error|warning)\s+\w+\s*:\s*(.*)$)");
  // GCC / Clang: /x/main.cpp:12:5: error: 'foo' was not declared in this scope
  static const std::regex gnu(R"(^(.+?):(\d+):(\d+):\s*(fatal error|error|warning|note):\s*(.*)$)");
  static const std::regex gnu_noline(R"(^(.+?):(\d+):\s*(fatal error|error|warning):\s*(.*)$)");
  // Linkers: main.cpp.obj : error LNK2019: ... / ld: ... undefined reference to `x'
  static const std::regex lnk(R"(^(.*?)\s*:\s*(fatal error|error)\s+(LNK\d+)\s*:\s*(.*)$)");
  static const std::regex cmake_err(R"(^CMake Error at (.+?):(\d+).*$)");
  std::smatch m;
  out = Issue{};
  if (std::regex_match(line, m, msvc)) {
    out.file = m[1];
    out.line = std::stoi(m[2]);
    out.column = m[3].matched ? std::stoi(m[3]) : 0;
    out.severity = severity_of(m[4]);
    out.message = m[5];
  } else if (std::regex_match(line, m, gnu)) {
    out.file = m[1];
    out.line = std::stoi(m[2]);
    out.column = std::stoi(m[3]);
    out.severity = severity_of(m[4]);
    out.message = m[5];
  } else if (std::regex_match(line, m, gnu_noline)) {
    out.file = m[1];
    out.line = std::stoi(m[2]);
    out.severity = severity_of(m[3]);
    out.message = m[4];
  } else if (std::regex_match(line, m, lnk)) {
    out.file = m[1];
    out.message = std::string(m[3]) + ": " + std::string(m[4]);
  } else if (line.find("undefined reference to") != std::string::npos ||
             line.find("Undefined symbols") != std::string::npos) {
    out.message = line;
  } else if (std::regex_match(line, m, cmake_err)) {
    out.file = m[1];
    out.line = std::stoi(m[2]);
    out.message = "CMake error";
  } else {
    return false;
  }
  const std::string f = cmake_path(out.file);
  out.user_code = f.size() >= 8 && f.compare(f.size() - 8, 8, "main.cpp") == 0;
  return true;
}

Builder::Builder() = default;

Builder::~Builder() {
  *alive_ = false;
  if (proc_) proc_->kill();
}

std::string Builder::build_dir() const {
  return (fs::path(project_dir_) / (req_.release ? "build-release" : "build")).string();
}

std::string Builder::executable() const {
  const fs::path b = build_dir();
#if defined(_WIN32)
  return (b / "app.exe").string();
#elif defined(__APPLE__)
  return (b / "app.app" / "Contents" / "MacOS" / "app").string();
#else
  return (b / "app").string();
#endif
}

void Builder::launch(const std::string& command, std::map<std::string, std::string> env, bool replace_env,
                     std::function<void(int)> done) {
  output.emit("> " + command);
  std::weak_ptr<bool> alive = alive_;
  Process::Options opt;
  opt.command = command;
  opt.env = std::move(env);
  opt.replace_env = replace_env;
  opt.cwd = project_dir_;
  proc_ = Process::start(
      opt,
      [this, alive](const std::string& line) {
        pulseui::App::post([this, alive, line] {
          if (!alive.expired()) on_line(line);
        });
      },
      [this, alive, done](int code) {
        pulseui::App::post([this, alive, done, code] {
          if (alive.expired()) return;
          proc_.reset();
          done(code);
        });
      });
  if (!proc_) {
    output.emit("failed to start: " + command);
    done(-1);
  }
}

void Builder::on_line(const std::string& line) {
  if (state.get() == Running) { // the program's own output
    app_output.emit(line);
    return;
  }
  output.emit(line);
  Issue is;
  // errors from anywhere, warnings/notes only from the user's code (not from PulseUI)
  if (state.get() != Running && parse_issue(line, is)) {
    // map the copy in build/src back to the project file
    const std::string base = fs::path(is.file).filename().string();
    is.user_code = !is.file.empty() &&
                   std::find(req_.user_files.begin(), req_.user_files.end(), base) != req_.user_files.end();
    if (is.user_code) is.file = base;
  }
  // errors from anywhere, warnings/notes only from the user's code (not from PulseUI)
  if (state.get() != Running && !is.message.empty() && (is.user_code || is.severity == pulseui::Diagnostic::Error)) {
    auto list = issues.get();
    if (std::find(list.begin(), list.end(), is) == list.end()) {
      list.push_back(is);
      issues = list;
    }
  }
}

bool Builder::build(const Request& r, bool run_after) {
  if (state.get() != Idle) return false;
  req_ = r;
  run_after_ = run_after;
  proc_killed_note_ = false;
  project_dir_ = r.project_dir;
  issues = std::vector<Issue>{};
  if (r.kit.cxx.empty()) {
    note.emit("build.no_kit", "");
    return false;
  }
  if (!r.cmake.found()) {
    note.emit("build.no_cmake", "");
    return false;
  }
  std::error_code ec;
  if (!fs::exists(fs::path(r.pulseui_dir) / "CMakeLists.txt", ec)) {
    note.emit("build.no_pulseui", r.pulseui_dir);
    return false;
  }

  const fs::path src = fs::path(project_dir_) / "src";
  std::string sources;
  for (auto& [name, text] : r.files) {
    const std::string ext = fs::path(name).extension().string();
    if (ext == ".cpp" || ext == ".cc" || ext == ".cxx") sources += (sources.empty() ? "" : " ") + name;
  }
  if (sources.empty()) sources = "main.cpp";
  // Debug builds: when Pulse Layer runs the program, std::cout / printf reach its
  // Application Output at once instead of when a 4 KB buffer fills up (stdout to a pipe is fully buffered).
  const bool console = !r.release;
  if (console) sources += std::string(" ") + kConsoleFile;
  // files removed from the project must not linger in the generated sources
  std::error_code rm_ec;
  if (fs::is_directory(src, rm_ec))
    for (auto& e : fs::directory_iterator(src, rm_ec)) {
      const std::string n = e.path().filename().string();
      if (n == "CMakeLists.txt" || (console && n == kConsoleFile)) continue;
      if (std::none_of(r.files.begin(), r.files.end(), [&](const auto& f) { return f.first == n; })) fs::remove(e.path(), rm_ec);
    }
  write_if_changed(src / "CMakeLists.txt",
                   "# Generated by Pulse Layer\n"
                   "cmake_minimum_required(VERSION 3.21)\n"
                   "project(PulseLayerApp CXX)\n"
                   "set(CMAKE_CXX_STANDARD 20)\n"
                   "set(CMAKE_EXPORT_COMPILE_COMMANDS ON) # used by the error check on save\n"
                   "set(PULSEUI_BUILD_EXAMPLES OFF CACHE BOOL \"\" FORCE)\n"
                   "set(PULSEUI_BUILD_TESTS OFF CACHE BOOL \"\" FORCE)\n"
                   "add_subdirectory(\"" + cmake_path(r.pulseui_dir) + "\" pulseui)\n"
                   "pulseui_add_app(app " + sources + ")\n"
                   "target_include_directories(app PRIVATE ${CMAKE_CURRENT_SOURCE_DIR})\n"
                   "if(MSVC)\n  target_compile_options(app PRIVATE /diagnostics:column /bigobj)\n"
                   "elseif(MINGW)\n  target_compile_options(app PRIVATE -Wa,-mbig-obj) # Debug builds of big forms overflow COFF sections\n"
                   "endif()\n");
  for (auto& [name, text] : r.files) write_if_changed(src / name, text);
  if (console) write_if_changed(src / kConsoleFile, kConsoleSource);

  env_ = kit_environment(r.kit, replace_env_);
  started_ = std::chrono::steady_clock::now();

  // A different kit needs a fresh CMake cache.
  const fs::path build_dir = this->build_dir();
  const fs::path stamp = build_dir / "pulselayer-kit.txt";
  release_result_.clear();
  const bool configured = fs::exists(build_dir / "CMakeCache.txt", ec) && read_file(stamp) == kit_stamp(r.kit);
  if (!configured) {
    fs::remove_all(build_dir, ec);
    fs::create_directories(build_dir, ec);
    write_if_changed(stamp, kit_stamp(r.kit));
    note.emit("build.first_time", "");
    step_configure();
  } else {
    step_build();
  }
  return true;
}

void Builder::step_configure() {
  state = Configuring;
  const fs::path src = fs::path(project_dir_) / "src";
  const fs::path build_dir = this->build_dir();
  std::string cmd = Process::quote(req_.cmake.path) + " -S " + Process::quote(src.string()) + " -B " +
                    Process::quote(build_dir.string()) + (req_.release ? " -DCMAKE_BUILD_TYPE=Release" : " -DCMAKE_BUILD_TYPE=Debug");
  if (req_.release) {
    // a self-contained program: the C/C++ runtime linked in, not a DLL to ship
    cmd += " -DCMAKE_MSVC_RUNTIME_LIBRARY=MultiThreaded";
#ifdef _WIN32
    if (req_.kit.kind == Kit::Kind::MinGW || req_.kit.kind == Kit::Kind::GCC) cmd += " -DCMAKE_EXE_LINKER_FLAGS=-static";
#endif
  }
  if (req_.ninja.found()) {
    cmd += " -G Ninja -DCMAKE_MAKE_PROGRAM=" + Process::quote(cmake_path(req_.ninja.path));
  } else {
#ifdef _WIN32
    cmd += req_.kit.kind == Kit::Kind::MinGW ? " -G \"MinGW Makefiles\"" : " -G \"NMake Makefiles\"";
#endif
  }
  cmd += " -DCMAKE_CXX_COMPILER=" + Process::quote(cmake_path(req_.kit.cxx));
  if (!req_.kit.libcxx_dir.empty()) {
    // Homebrew LLVM: link its libc++ (the system one lacks newer symbols such as
    // std::__hash_memory). A release also looks in the bundle, where package() copies it.
    std::error_code ec;
    const fs::path cxx_lib = req_.kit.libcxx_dir;
    const fs::path unwind = cxx_lib.parent_path() / "unwind";
    std::string flags = "-L" + cxx_lib.string() + " -Wl,-rpath," + cxx_lib.string();
    if (fs::exists(unwind / "libunwind.1.dylib", ec)) flags += " -L" + unwind.string() + " -Wl,-rpath," + unwind.string() + " -lunwind";
    if (req_.release) flags += " -Wl,-rpath,@executable_path/../Frameworks";
    cmd += " -DCMAKE_EXE_LINKER_FLAGS=" + Process::quote(flags);
  }
  launch(cmd, env_, replace_env_, [this](int code) {
    if (code != 0) return finish_build(false);
    step_build();
  });
}

void Builder::step_build() {
  state = Building;
  const fs::path build_dir = this->build_dir();
  launch(Process::quote(req_.cmake.path) + " --build " + Process::quote(build_dir.string()), env_, replace_env_,
         [this](int code) { finish_build(code == 0); });
}

void Builder::finish_build(bool ok) {
  last_ok_ = ok;
  if (ok && req_.release) return package();
  state = Idle;
  const double secs = std::chrono::duration<double>(std::chrono::steady_clock::now() - started_).count();
  if (ok) {
    char buf[32];
    std::snprintf(buf, sizeof buf, "%.1f", secs);
    note.emit("build.ok", buf);
    if (run_after_) run();
  } else {
    int errors = 0;
    for (auto& i : issues.get()) errors += i.severity == pulseui::Diagnostic::Error;
    note.emit(proc_killed_note_ ? "build.stopped" : "build.failed", std::to_string(errors));
  }
}

bool Builder::check(const Request& r, std::function<void(std::vector<Issue>)> done) {
  if (state.get() != Idle || r.kit.cxx.empty()) return false;
  const fs::path build_dir = fs::path(r.project_dir) / "build";
  const fs::path src = fs::path(r.project_dir) / "src";
  const auto db = pulseui::json::Value::parse(read_file(build_dir / "compile_commands.json"));
  if (!db || !db->is_array() || read_file(build_dir / "pulselayer-kit.txt") != kit_stamp(r.kit)) return false;
  for (auto& [name, text] : r.files) write_if_changed(src / name, text);

  // the exact commands of the user's .cpp files
  struct Job {
    std::string command, dir;
  };
  std::vector<Job> jobs;
  const bool msvc_style = r.kit.kind == Kit::Kind::MSVC || r.kit.kind == Kit::Kind::ClangMSVC;
  for (auto& e : db->items()) {
    const std::string file = fs::path(e["file"].as_string()).filename().string();
    if (std::find(r.user_files.begin(), r.user_files.end(), file) == r.user_files.end()) continue;
    std::string cmd = e["command"].as_string();
    if (cmd.empty())
      for (auto& a : e["arguments"].items()) cmd += (cmd.empty() ? "" : " ") + Process::quote(a.as_string());
    if (cmd.empty()) continue;
    jobs.push_back({cmd + (msvc_style ? " /Zs" : " -fsyntax-only"), e["directory"].as_string()});
  }
  if (jobs.empty()) return false;
  bool replace = false;
  auto env = kit_environment(r.kit, replace);
  const std::vector<std::string> user = r.user_files;
  std::weak_ptr<bool> alive = alive_;
  std::thread([jobs, env, replace, user, alive, done] {
    std::vector<Issue> found;
    for (auto& j : jobs) {
      std::string out;
      Process::run(j.command, out, 120000, env, replace, j.dir);
      std::istringstream lines(out);
      for (std::string line; std::getline(lines, line);) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        Issue is;
        if (!parse_issue(line, is) || is.message.empty()) continue;
        const std::string base = fs::path(is.file).filename().string();
        is.user_code = !is.file.empty() && std::find(user.begin(), user.end(), base) != user.end();
        if (is.user_code) is.file = base;
        if ((is.user_code || is.severity == pulseui::Diagnostic::Error) &&
            std::find(found.begin(), found.end(), is) == found.end())
          found.push_back(is);
      }
    }
    pulseui::App::post([alive, done, found] {
      if (!alive.expired()) done(found);
    });
  }).detach();
  return true;
}

void Builder::package() {
  std::error_code ec;
  const fs::path dir = req_.release_dir.empty() ? fs::path(project_dir_) / "release" : fs::path(req_.release_dir);
  fs::remove_all(dir, ec);
  fs::create_directories(dir, ec);
  const std::string name = req_.app_name.empty() ? std::string("app") : req_.app_name;
  auto done = [this](bool ok, const std::string& result) {
    last_ok_ = ok;
    state = Idle;
    release_result_ = ok ? result : std::string();
    note.emit(ok ? "release.done" : "release.failed", result);
  };
#if defined(_WIN32)
  std::string error;
  const auto dlls = deploy_windows(executable(), dir.string(), name, req_.kit, env_, &error);
  if (!error.empty()) {
    output.emit("release: " + error);
    return done(false, error);
  }
  output.emit("release: " + (dir / (name + ".exe")).string());
  for (auto& d : dlls) output.emit("release:   + " + d);
  if (dlls.empty()) output.emit("release:   (no DLLs needed: the runtime is linked into the program)");
  done(true, dir.string());
#elif defined(__APPLE__)
  // <build>/app.app -> release/<Name>.app, signed, then a disk image next to it
  const fs::path bundle = fs::path(build_dir()) / "app.app";
  const fs::path target = dir / (name + ".app");
  fs::copy(bundle, target, fs::copy_options::recursive | fs::copy_options::overwrite_existing, ec);
  if (ec) {
    output.emit("release: " + ec.message());
    return done(false, ec.message());
  }
  if (!req_.kit.libcxx_dir.empty()) {
    // Homebrew's libc++ is not on other Macs: ship it inside the bundle
    const fs::path fw = target / "Contents" / "Frameworks";
    fs::create_directories(fw, ec);
    const fs::path cxx_lib = req_.kit.libcxx_dir;
    for (const fs::path& lib : {cxx_lib / "libc++.1.dylib", cxx_lib / "libc++abi.1.dylib", cxx_lib.parent_path() / "unwind" / "libunwind.1.dylib"}) {
      if (!fs::exists(lib, ec)) continue;
      fs::copy_file(fs::canonical(lib, ec), fw / lib.filename(), fs::copy_options::overwrite_existing, ec);
      output.emit("release:   + " + lib.filename().string());
    }
  }
  const std::string identity = req_.sign_identity.empty() ? std::string("-") : req_.sign_identity;
  state = Building;
  launch("codesign --force --deep --options runtime --sign " + Process::quote(identity) + " " + Process::quote(target.string()), env_,
         replace_env_, [this, dir, name, target, done](int code) {
           if (code != 0) return done(false, "codesign");
           const fs::path dmg = dir / (name + ".dmg");
           launch("hdiutil create -volname " + Process::quote(name) + " -srcfolder " + Process::quote(target.string()) +
                      " -ov -format UDZO " + Process::quote(dmg.string()),
                  env_, replace_env_, [done, dir](int c2) { done(c2 == 0, dir.string()); });
         });
#else
  fs::copy_file(executable(), dir / name, fs::copy_options::overwrite_existing, ec);
  done(!ec, ec ? ec.message() : dir.string());
#endif
}

bool Builder::run() {
  if (state.get() != Idle) return false;
  std::error_code ec;
  if (!fs::exists(executable(), ec)) return false;
  state = Running;
  proc_killed_note_ = false;
  note.emit("run.started", "");
  auto env = env_;
  env["PULSELAYER_CONSOLE"] = "1";
  launch(Process::quote(executable()), std::move(env), replace_env_, [this](int code) {
    state = Idle;
    note.emit("run.exit", std::to_string(code));
  });
  return true;
}

void Builder::stop() {
  if (proc_) {
    proc_killed_note_ = true;
    proc_->kill();
  }
}

} // namespace layer
